import React, { useState } from 'react';
import { useParams } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';
import Modal from '../components/Modal';
import { useNavigate } from 'react-router-dom';

const Wrapper = styled.div`
  max-width: 700px;
  margin: 3em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
  min-height: 60vh;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;

const InfoBox = styled.div`
  background: #f5f8ff;
  border-radius: 0.7em;
  padding: 1em 1em 0.7em 1em;
  margin-bottom: 1.2em;
  color: #234;
  font-size: 1.08em;
`;
function TeacherSessionDetail() {
  const navigate = useNavigate(); // 페이지 이동용
  const [modalOpen, setModalOpen] = useState(false); // 평가 기준 수정 모달 열림 여부
  const [criteriaValue, setCriteriaValue] = useState(''); // 모달 내 평가 기준 입력값
  const [studentModal, setStudentModal] = useState({ open: false, student: null }); // (미사용) 학생 상세 모달 상태
  // 세션 ID는 URL 파라미터로 받아옴
  // 실제로는 useParams 등으로 id 받아와 fetch 필요
  const { id } = useParams(); // 세션 id (라우트 파라미터)
  // 임시 더미 데이터 (id별 분기)
  const [criteria, setCriteria] = useState(''); // 현재 평가 기준(수정 반영용)
  
  
  // 세션 상세 데이터 fetch 함수 (id로 조회)
  async function fetchSessionDetail(sessionId) {
    const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-detail', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: sessionId }),
    });
    if (!res.ok) throw new Error('세션 데이터 조회 실패');
    return await res.json();
  }

  // 세션 상세 데이터 state
  const [data, setData] = useState(null); // {id, name, code, created_at, criteria, students}
  const [loading, setLoading] = useState(true);
  
  React.useEffect(() => {
    // id 변경 시 세션 상세 fetch
    let ignore = false;
    setLoading(true);
    fetchSessionDetail(id)
      .then(res => {
        if (!ignore) {
          // API 응답 구조에 따라 세션 정보 추출
          let sessionData = res;
          if (res && res.ok && res.session) {
            sessionData = res.session;
          }
          setData(sessionData);
          setCriteria(sessionData.criteria || sessionData.criteriaValue || '');
        }
      })
      .catch(() => {
        // fetch 실패 시 더미 데이터 사용
        setData(null);
        setCriteria(null);
      })
      .finally(() => {
        setLoading(false);
      });
    return () => { ignore = true; };
    // eslint-disable-next-line
  }, [id]);

  if (loading || !data) {
    return (
      <Wrapper>
        <div style={{ textAlign: 'center', color: '#888', marginTop: 60 }}>세션 정보를 불러오는 중...</div>
      </Wrapper>
    );
  }

  // students가 없거나 배열이 아니면 빈 배열로 대체 (API 오류 방지)
  const students = Array.isArray(data.students) ? data.students : [];

  return (
    <Wrapper>
      {/* 세션 상세 타이틀 */}
      <Title>세션 상세</Title>
      <Button variant="outline" size="sm" style={{ marginBottom: 18 }} onClick={() => navigate(-1)}>
        뒤로가기
      </Button>
      {/* 세션 정보 및 평가 기준 */}
      <InfoBox>
        <b>세션명:</b> {data.title}<br />
        <b>참여코드:</b> {data.code} {/* 참여코드 복사 버튼 */}
        <Button size="sm" style={{ marginLeft: 8 }} onClick={() => navigator.clipboard.writeText(data.code)}>복사</Button><br />
        <b>생성일:</b> {data.created_at}<br />
        <b>평가 기준:</b> {criteria}
        {/* 평가 기준 수정 버튼 */}
        <Button size="sm" variant="outline" style={{ marginLeft: 12 }} onClick={() => { setCriteriaValue(criteria); setModalOpen(true); }}>평가 기준 수정</Button>
      </InfoBox>
      {/* 평가 기준 수정 모달 */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
        <div style={{ minWidth: 260 }}>
          <h3 style={{ marginBottom: 16 }}>평가 기준 수정</h3>
          <textarea
            style={{ width: '100%', minHeight: 80, fontSize: '1.08em', borderRadius: 8, border: '1.5px solid #bfc8e6', padding: 10, marginBottom: 18 }}
            value={criteriaValue}
            onChange={e => setCriteriaValue(e.target.value)}
            maxLength={200}
            autoFocus
          />
          <div style={{ display: 'flex', gap: 8 }}>
            {/* 저장: 평가 기준 state 반영, 모달 닫기 */}
            <Button onClick={() => { setCriteria(criteriaValue); setModalOpen(false); }} style={{ flex: 1 }}>
              저장
            </Button>
            {/* 취소: 모달 닫기 */}
            <Button variant="outline" onClick={() => setModalOpen(false)} style={{ flex: 1 }}>
              취소
            </Button>
          </div>
        </div>
      </Modal>
      {/* 전체 글 열람 페이지 이동 버튼 */}
      <div style={{ marginBottom: 18 }}>
        <Button size="sm" variant="outline" onClick={() => navigate(`/teacher/sessions/${id}/all-writings`)}>
          전체 글 열람 (AI 챗봇)
        </Button>
      </div>
      {/* 학생 명단 및 제출 상태 테이블 */}
      <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 6, fontSize: '1.08em' }}>학생 명단 및 제출 상태</div>
      <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: 18 }}>
        <thead>
          <tr style={{ background: '#f5f8ff' }}>
            <th style={{ padding: '0.5em', textAlign: 'left' }}>이름</th>
            <th style={{ padding: '0.5em', textAlign: 'left' }}>입장일</th>
            <th style={{ padding: '0.5em', textAlign: 'left' }}>제출 여부</th>
            <th style={{ padding: '0.5em', textAlign: 'left' }}>제출 시각</th>
            <th style={{ padding: '0.5em', textAlign: 'left' }}>글/피드백</th>
          </tr>
        </thead>
        <tbody>
          {/* 학생별 행 렌더링 */}
          {students.map(stu => (
            <tr key={stu.name}>
              <td style={{ padding: '0.5em' }}>{stu.name}</td>
              <td style={{ padding: '0.5em' }}>{stu.joined_at}</td>
              <td style={{ padding: '0.5em' }}>{stu.submitted ? 'O' : '-'}</td>
              <td style={{ padding: '0.5em' }}>{stu.submitted_at || '-'}</td>
              <td style={{ padding: '0.5em' }}>
                {/* 학생 글/피드백 상세 페이지 이동: 세션id와 학생이름을 전달 */}
                <Button size="sm" onClick={() => navigate(`/teacher/sessions/${id}/student/${encodeURIComponent(stu.name)}`)}>
                  열람
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {/* 학생 글/피드백 모달 제거: 별도 페이지에서 열람 */}
    </Wrapper>
  );
}

export default TeacherSessionDetail;
