import GlobalStyle from './components/GlobalStyle';
import Header from './components/Header';
import Footer from './components/Footer';
import React, { useState } from 'react';
import Toast from './components/Toast';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { RecoilRoot } from 'recoil';
import { ThemeProvider } from 'styled-components';
import { lightTheme, darkTheme } from './components/theme';
import Button from './components/Button';
import Input from './components/Input';
import LoadingSpinner from './components/LoadingSpinner';
import Modal from './components/Modal';


import TeacherSessionList from './pages/TeacherSessionList';
import TeacherSessionDetail from './pages/TeacherSessionDetail';
import TeacherStudentDetail from './pages/TeacherStudentDetail';
import TeacherSessionAllWritings from './pages/TeacherSessionAllWritings';
import TeacherLogin from './pages/TeacherLogin';
import TeacherSessionCreate from './pages/TeacherSessionCreate';

import SessionEntry from './pages/SessionEntry';
import WritingEditor from './pages/WritingEditor';
import FeedbackView from './pages/FeedbackView';


function Home() {
  const [modalOpen, setModalOpen] = useState(false);
  const [inputValue, setInputValue] = useState('');

  // user prop을 받아 로그인 상태 표시
  return (
    <div style={{ padding: '2em', maxWidth: 480, margin: '0 auto' }}>
      <h2>공통 UI 컴포넌트 예시</h2>
      <div style={{ margin: '1.5em 0', color: '#234', fontWeight: 500 }}>
        {/* 로그인 상태 표시 */}
        {typeof window !== 'undefined' && window.fw_user && window.fw_user.email ? (
          <span>로그인됨: {window.fw_user.email}</span>
        ) : null}
      </div>
      <div style={{ margin: '1.5em 0' }}>
        <Button onClick={() => alert('버튼 클릭!')}>기본 버튼</Button>{' '}
        <Button variant="outline" onClick={() => alert('아웃라인 버튼!')}>아웃라인 버튼</Button>
      </div>
      <div style={{ margin: '1.5em 0' }}>
        <Input
          placeholder="입력 예시..."
          value={inputValue}
          onChange={e => setInputValue(e.target.value)}
          style={{ maxWidth: 300 }}
        />
      </div>
      <div style={{ margin: '1.5em 0' }}>
        <Button onClick={() => setModalOpen(true)}>모달 열기</Button>
        <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
          <div style={{ minWidth: 200 }}>
            <h3>모달 예시</h3>
            <p>이곳에 원하는 내용을 넣을 수 있습니다.</p>
            <Button onClick={() => setModalOpen(false)}>닫기</Button>
          </div>
        </Modal>
      </div>
      <div style={{ margin: '1.5em 0' }}>
        <span>로딩스피너: </span>
        <LoadingSpinner />
      </div>
    </div>
  );
}



function App() {
  const [toast, setToast] = useState({ visible: false, message: '' });
  const [dark, setDark] = useState(false);
  // 간단한 로그인 상태 관리 (실제 서비스는 context/redux 등 권장)
  const [user, setUser] = useState(() => {
    try {
      const saved = localStorage.getItem('fw_user');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  }); // {id, email, ...}
  const [loginLoading, setLoginLoading] = useState(false);

  // Supabase 로그인 성공 시 user 객체를 저장
  // onLogin(email, password, user) 형태로 호출됨
  const handleLogin = async (email, password, userObj) => {
    setLoginLoading(true);
    if (userObj && userObj.id && userObj.email) {
      const userData = {
        id: userObj.id,
        email: userObj.email,
        access_token: userObj.access_token || userObj.accessToken || (userObj.session && userObj.session.access_token),
        ...userObj
      };
      setUser(userData);
      try {
        localStorage.setItem('fw_user', JSON.stringify(userData));
      } catch {}
    }
    setLoginLoading(false);
  };
  // 로그아웃 함수: 상태와 localStorage 모두 초기화
  const handleLogout = () => {
    setUser(null);
    try {
      localStorage.removeItem('fw_user');
    } catch {}
  };

  // user를 Home에 prop으로 전달
  return (
    <RecoilRoot>
      <ThemeProvider theme={dark ? darkTheme : lightTheme}>
        <GlobalStyle />
        <Header />
        <button
          style={{
            position: 'fixed',
            top: 16,
            right: 16,
            zIndex: 2001,
            background: '#fff',
            border: '1px solid #bfc8e6',
            borderRadius: 8,
            padding: '0.5em 1em',
            cursor: 'pointer',
            fontWeight: 600,
          }}
          onClick={() => setDark((d) => !d)}
        >
          {dark ? '라이트모드' : '다크모드'}
        </button>
        <Router basename="/feed_writer">
        <Routes>
          <Route path="/" element={<SessionEntry />} />
          <Route path="/entry" element={<SessionEntry />} />
          <Route path="/test-writing" element={<WritingEditor />} />
          <Route path="/feedback-test" element={<FeedbackView />} />
          {/* 교사 로그인 */}
          <Route path="/teacher/login" element={<TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
          {/* 교사 세션 생성 (로그인 필요) */}
          <Route path="/teacher/sessions/create" element={user ? <TeacherSessionCreate user={user} /> : <TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
          {/* 교사 세션 목록 (로그인 필요) */}
          <Route path="/teacher/sessions" element={user ? <TeacherSessionList user={user} /> : <TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
          <Route path="/teacher/sessions/:id" element={user ? <TeacherSessionDetail user={user} /> : <TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
          <Route path="/teacher/sessions/:id/all-writings" element={user ? <TeacherSessionAllWritings user={user} /> : <TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
          <Route path="/teacher/sessions/:sessionId/student/:studentName" element={user ? <TeacherStudentDetail user={user} /> : <TeacherLogin onLogin={handleLogin} loading={loginLoading} />} />
        </Routes>
        </Router>
        <Toast visible={toast.visible} message={toast.message} />
        <Footer />
      </ThemeProvider>
    </RecoilRoot>
  );
}

export default App;
