import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';
import Modal from '../components/Modal';
import Input from '../components/Input';

const Wrapper = styled.div`
  max-width: 1000px;
  margin: 3em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
  min-height: 60vh;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 2em;
  th, td {
    border-bottom: 1px solid #e0e6f7;
    padding: 0.7em 0.5em;
    text-align: left;
  }
  th {
    color: #2d5be3;
    font-weight: 700;
    background: #f5f8ff;
  }
`;


function randomCode() {
  // 6자리 영문+숫자 랜덤 코드
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

function TeacherSessionList({ user }) {
  const navigate = useNavigate();
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [newtitle, setNewtitle] = useState('');
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    // 실제 API 연동 (Supabase Edge Function)
    let ignore = false;
    setLoading(true);
    fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-list', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(user?.access_token ? { 'Authorization': `Bearer ${user.access_token}` } : {})
      },
      body: JSON.stringify({
        teacherId: user.id, // 또는 teacherEmail 등
        // 기타 필요한 인증/필터 정보
      }),
    })
      .then(res => {
        if (!res.ok) throw new Error('세션 목록 조회 실패');
        return res.json();
      })
      .then(data => {
        if (!ignore) setSessions(data.sessions || []);
      })
      .catch(() => {
        // 네트워크 오류 등 fallback: 더미 데이터
        setSessions([
          { id: '1', title: '환경 글쓰기', code: 'ABC123', created_at: '2025-06-01' },
          { id: '2', title: '여름방학 계획', code: 'DEF456', created_at: '2025-06-05' },
        ]);
      })
      .finally(() => {
        setLoading(false);
      });
    return () => { ignore = true; };
  }, [user]);


  return (
    <Wrapper>
      <Title>세션 목록</Title>
      <Button style={{ marginBottom: 18 }} onClick={() => navigate('/teacher/sessions/create')}>+ 새 세션 만들기</Button>
      {/* 새 세션 만들기 모달 제거: 생성 페이지로 이동 방식으로 변경됨 */}
      {loading ? (
        <div>로딩 중...</div>
      ) : (
        <Table>
          <thead>
            <tr>
              <th>세션명</th>
              <th>참여코드</th>
              <th>생성일</th>
              <th>상세</th>
            </tr>
          </thead>
          <tbody>
            {sessions.map(s => (
              <tr key={s.id}>
                <td>{s.title}</td>
                <td>{s.code}</td>
                <td>{s.created_at}</td>
                <td><Button size="sm" onClick={() => navigate(`/teacher/sessions/${s.id}`)}>보기</Button></td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </Wrapper>
  );
}

export default TeacherSessionList;
