import React from 'react';
import styled, { css } from 'styled-components';

const StyledButton = styled.button`
  display: inline-block;
  padding: 0.7em 1.5em;
  font-size: 1.1rem;
  border-radius: 0.5em;
  border: none;
  background: #2d5be3;
  color: #fff;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  &:hover:enabled {
    background: #1741a6;
  }
  &:disabled {
    background: #bfc8e6;
    color: #fff;
    cursor: not-allowed;
  }
  ${props =>
    props.$variant === 'outline' &&
    css`
      background: #fff;
      color: #2d5be3;
      border: 2px solid #2d5be3;
      &:hover:enabled {
        background: #eaf0fb;
      }
    `}
`;

function Button({ children, variant = 'default', ...rest }) {
  return (
    <StyledButton $variant={variant} {...rest}>
      {children}
    </StyledButton>
  );
}

export default Button;
