import React from 'react';
import styled from 'styled-components';

const FooterWrap = styled.footer`
  width: 100%;
  background: #f1f3f6;
  color: #888;
  padding: 1rem 0;
  text-align: center;
  font-size: 1rem;
  position: fixed;
  left: 0;
  bottom: 0;
`;

function Footer() {
  return <FooterWrap>© 2025 학교 글쓰기 플랫폼</FooterWrap>;
}

export default Footer;
