import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';
import Input from '../components/Input';
import Toast from '../components/Toast';



// 실제 API 연동 함수 (Supabase Edge Function 예시)
// https://supabase.com/docs/guides/functions
async function checkSessionEntry({ code, name }) {
  // 예: POST https://<YOUR_PROJECT>.functions.supabase.co/check-session-entry
  // body: { code, name }
  const SUPABASE_FUNCTION_URL = 'https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-entry';
  const res = await fetch(SUPABASE_FUNCTION_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ code, name }),
  });
//   if (!res.ok) throw new Error('서버 오류');
  return await res.json();
}

const Wrapper = styled.div`
  max-width: 400px;
  margin: 4em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
  text-align: center;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;




function SessionEntry({ onSubmit }) {
  const navigate = useNavigate();
  const [code, setCode] = useState('');
  const [name, setName] = useState('');
  const [toast, setToast] = useState({ visible: false, message: '' });
  const [pending, setPending] = useState(false);

  const handleSubmit = async e => {
    e.preventDefault();
    // 참여코드: 6자리 영문/숫자
    if (!/^[A-Z0-9]{6}$/.test(code)) {
      setToast({ visible: true, message: '참여코드는 6자리 영문/숫자여야 합니다.' });
      setTimeout(() => setToast({ visible: false, message: '' }), 2000);
      return;
    }
    // 이름: 2~12자
    if (!name.trim() || name.length < 2) {
      setToast({ visible: true, message: '이름을 2자 이상 입력하세요.' });
      setTimeout(() => setToast({ visible: false, message: '' }), 2000);
      return;
    }
    setPending(true);
    try {
      const result = await checkSessionEntry({ code, name });
      // result: { ok: boolean, error?: string }
      // 중복 접속 에러는 무시하고 입장 허용
      if (!result.ok && result.error !== '이미 접속 중') {
        setToast({ visible: true, message: result.error || '입장 불가' });
        setPending(false);
        setTimeout(() => setToast({ visible: false, message: '' }), 2200);
        return;
      }
      setPending(false);
      if (onSubmit) onSubmit({ code, name });
      // 글쓰기 화면으로 이동 (참여코드와 이름을 쿼리스트링으로 전달)
      navigate(`/test-writing?code=${encodeURIComponent(code)}&name=${encodeURIComponent(name)}`);
    } catch (err) {
      setToast({ visible: true, message: '서버 오류: ' + err.message });
        console.error('Session entry error:', err);
      setPending(false);
      setTimeout(() => setToast({ visible: false, message: '' }), 2200);
    }
  };

  return (
    <Wrapper>
      <Title>세션 입장</Title>
      <form onSubmit={handleSubmit}>
        <Input
          placeholder="참여코드 (6자리)"
          maxLength={6}
          value={code}
          onChange={e => setCode(e.target.value.replace(/[^A-Za-z0-9]/g, '').toUpperCase())}
          style={{ marginBottom: 16 }}
          autoFocus
          disabled={pending}
        />
        <Input
          placeholder="이름"
          maxLength={12}
          value={name}
          onChange={e => setName(e.target.value)}
          style={{ marginBottom: 24 }}
          disabled={pending}
        />
        <Button type="submit" style={{ width: '100%' }} disabled={pending}>
          {pending ? '확인 중...' : '입장하기'}
        </Button>
      </form>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginTop: 18 }}>
        <Button
          variant="outline"
          style={{ width: '100%', fontSize: '1.07em' }}
          onClick={() => navigate('/teacher/login')}
        >
          교사용 로그인
        </Button>
        {/* 새로고침 시 항상 첫화면이므로 홈 버튼은 비노출 */}
      </div>
      <Toast visible={toast.visible} message={toast.message} />
    </Wrapper>
  );
}

export default SessionEntry;
