import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';

const Wrapper = styled.div`
  width: 95vw;
  margin: 32px auto 10px auto;
  background: ${({ theme }) => theme.card};
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 32px 18px 24px 18px;
  min-height: 60vh;
  overflow-x: auto;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;


function TeacherStudentDetail() {
  // 제출 글 드래그 감지용 ref
  // 코멘트 입력 UI 상태
  const [selection, setSelection] = React.useState(null); // {start, end, text}
  const [showCommentBox, setShowCommentBox] = React.useState(false);
  const [commentInput, setCommentInput] = React.useState('');
  const [commentRanges, setCommentRanges] = React.useState([]); // [{start, end, text, comment}]
  // 제출 글 드래그 감지용 ref
  const writingRef = React.useRef(null);
  const { sessionId, studentName } = useParams();
  // 세션 코드도 URL 파라미터로 받을 수 있도록 (예: /teacher/sessions/:sessionId/student/:studentName?code=XXX)
  // 또는 sessionId가 곧 세션 코드라면 그대로 사용
  // 필요시 아래처럼 쿼리스트링에서 code도 추출 가능
  // import { useLocation } from 'react-router-dom';
  // const location = useLocation();
  // const params = new URLSearchParams(location.search);
  // const sessionCode = params.get('code') || sessionId;
  const navigate = useNavigate();
  const [student, setStudent] = React.useState(null); // {name, joined_at, submitted, submitted_at, writing, feedback, topic}
  const [feedbackValue, setFeedbackValue] = React.useState('');
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);
  const [toast, setToast] = React.useState(null);
  const [feedbackHistory, setFeedbackHistory] = React.useState([]); // [{feedback, created_at}]
  const [criteriaScore, setCriteriaScore] = React.useState({}); // {criteria1: 0, ...}
  const [allowRewrite, setAllowRewrite] = React.useState(false); // 재작성 허용 여부

  // 실제 데이터 fetch (예시: Supabase Edge Function)
  React.useEffect(() => {
    let ignore = false;
    async function fetchStudentDetail() {
      setLoading(true);
      try {
        // Supabase Edge Function 연동 (POST 방식)
        const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/student-detail', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessionId, studentName })
        });
        const data = await res.json();
        if (!ignore) {
          setStudent(data.student); // {name, joined_at, submitted, submitted_at, writing, feedback, topic}
          setFeedbackValue(data.student.feedback || '');
          setFeedbackHistory(data.feedbackHistory || []); // [{feedback, created_at}]
          setCriteriaScore(data.criteriaScore || {});
          setCommentRanges(data.comments || []); // commentRanges(코멘트 배열)도 fetch
          setAllowRewrite(typeof data.allowRewrite === 'boolean' ? data.allowRewrite : !!data.student.allowRewrite);
        }
      } catch (e) {
        setToast({ type: 'error', message: '학생 글/피드백 조회에 실패했습니다.' });
      } finally {
        setLoading(false);
      }
    }
    fetchStudentDetail();
    return () => { ignore = true; };
  }, [sessionId, studentName]);

  // 피드백+코멘트 저장
  async function handleSaveFeedback() {
    if (!student || !student.submitted) return;
    setSaving(true);
    setToast(null);
    try {
      // Supabase Edge Function 연동
      const res = await fetch(`/functions/v1/save-feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId,
          studentName,
          feedback: feedbackValue,
          comments: commentRanges, // commentRanges도 함께 저장
          allowRewrite,
        }),
      });
      if (!res.ok) throw new Error('저장 실패');
      setToast({ type: 'success', message: '피드백이 저장되었습니다.' });
      setTimeout(() => {
        setToast(null);
      }, 1800);
      // 최신 데이터 fetch (POST 방식)
      const refetch = await fetch('/functions/v1/student-detail', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId, studentName })
      });
      if (refetch.ok) {
        const data = await refetch.json();
        setStudent(data.student);
        setFeedbackHistory(data.feedbackHistory || []);
        setCommentRanges(data.comments || []); // 최신 코멘트 반영
        setAllowRewrite(typeof data.allowRewrite === 'boolean' ? data.allowRewrite : !!data.student.allowRewrite);
      }
    } catch (e) {
      setToast({ type: 'error', message: '피드백 저장에 실패했습니다.' });
    } finally {
      setSaving(false);
    }
  }

  return (
    <Wrapper>
      <Title>학생 글/피드백 상세</Title>
      <div style={{ display: 'flex', gap: 10, marginBottom: 16 }}>
        <Button variant="outline" size="sm" onClick={() => navigate(-1)}>&lt; 뒤로가기</Button>
        <Button variant="outline" size="sm" onClick={() => navigate('/')} >처음화면</Button>
      </div>
      {toast && (
        <div style={{ marginBottom: 12, color: toast.type === 'success' ? '#2d5be3' : '#e33d2d', fontWeight: 500, fontSize: '1.05em' }}>{toast.message}</div>
      )}
      {loading ? (
        <div style={{ textAlign: 'center', color: '#888', marginTop: 60 }}>로딩 중...</div>
      ) : !student ? (
        <div style={{ textAlign: 'center', color: '#c00', marginTop: 60 }}>학생 데이터를 불러올 수 없습니다.</div>
      ) : (
        <div
          style={{
            display: 'flex',
            gap: 24,
            alignItems: 'flex-start',
            flexWrap: 'nowrap',
            minHeight: 320,
            overflowX: 'auto',
            width: '100%',
            boxSizing: 'border-box',
          }}
        >
          {/* 1. 글 정보 */}
          <div style={{ flex: '1 1 0', minWidth: 0, background: '#f5f8ff', borderRadius: 10, padding: '1.2em 1em', fontSize: '1.07em', boxSizing: 'border-box', wordBreak: 'break-all' }}>
            <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 8 }}>글 정보</div>
            <div style={{ marginBottom: 8 }}><b>이름:</b> {student.name}</div>
            <div style={{ marginBottom: 8 }}><b>입장일:</b> {student.joined_at}</div>
            <div style={{ marginBottom: 8 }}><b>제출 여부:</b> {student.submitted ? 'O' : '-'}</div>
            <div style={{ marginBottom: 8 }}><b>제출 시각:</b> {student.submitted_at || '-'}</div>
            <div style={{ marginBottom: 8 }}><b>글 주제:</b> {student.topic || '환경 보호'}</div>
            <div style={{ marginBottom: 8 }}><b>평가 기준:</b><br />
              <span style={{ color: '#234', fontSize: '0.98em' }}>
                1. 주제에 맞는 글을 썼는가?<br />
                2. 문단 구성이 논리적인가?<br />
                3. 맞춤법과 띄어쓰기가 올바른가?<br />
                4. 자신의 생각이 잘 드러나는가?
              </span>
            </div>
            {/* 평가(루브릭) 입력 UI 틀 */}
            <div style={{ marginTop: 18 }}>
              <b>평가 입력(베타):</b>
              <div style={{ marginTop: 6, fontSize: '0.98em', color: '#234' }}>
                {[1,2,3,4].map(i => (
                  <div key={i} style={{ marginBottom: 4 }}>
                    기준{i}: <input type="number" min={0} max={5} step={1} style={{ width: 40, fontSize: '1em', borderRadius: 4, border: '1px solid #bfc8e6', padding: '2px 6px' }}
                      value={criteriaScore[`criteria${i}`] || ''}
                      onChange={e => setCriteriaScore(cs => ({ ...cs, [`criteria${i}`]: e.target.value }))}
                    /> /5
                  </div>
                ))}
                <Button size="xs" style={{ marginTop: 6 }} disabled>평가 저장(준비중)</Button>
              </div>
            </div>
          </div>
          {/* 2. 제출 글 */}
          <div style={{ flex: '1 1 0', minWidth: 0, background: '#f9f9f9', borderRadius: 10, padding: '1.2em 1em', fontSize: '1.09em', maxHeight: 420, overflowY: 'auto', boxSizing: 'border-box', position: 'relative' }}>
            <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 8 }}>제출 글</div>
            {student.submitted ? (
              <>
                <pre
                  ref={writingRef}
                  style={{ whiteSpace: 'pre-wrap', wordBreak: 'break-all', margin: 0, fontFamily: 'inherit', fontSize: '1em', color: '#222', minHeight: 80 }}
                  onMouseUp={() => {
                    const sel = window.getSelection();
                    if (!sel || sel.isCollapsed) return;
                    const anchorNode = sel.anchorNode;
                    if (!writingRef.current.contains(anchorNode)) return;
                    const text = sel.toString();
                    if (!text) return;

                    // 하이라이트(span)가 있어도 정확한 인덱스 계산
                    function getAbsoluteOffset(node, offset) {
                      let abs = 0;
                      function traverse(current) {
                        if (current === node) {
                          abs += offset;
                          throw abs; // break all recursion
                        }
                        if (current.nodeType === Node.TEXT_NODE) {
                          abs += current.textContent.length;
                        } else if (current.nodeType === Node.ELEMENT_NODE) {
                          for (let child of current.childNodes) {
                            traverse(child);
                          }
                        }
                      }
                      try { traverse(writingRef.current); } catch (result) { return result; }
                      return 0;
                    }

                    const start = Math.min(
                      getAbsoluteOffset(sel.anchorNode, sel.anchorOffset),
                      getAbsoluteOffset(sel.focusNode, sel.focusOffset)
                    );
                    const end = Math.max(
                      getAbsoluteOffset(sel.anchorNode, sel.anchorOffset),
                      getAbsoluteOffset(sel.focusNode, sel.focusOffset)
                    );
                    setSelection({ start, end, text });
                    setShowCommentBox(true);
                    setCommentInput('');
                  }}
                >
                  {renderWritingWithComments(student.writing, commentRanges)}
                </pre>
                {/* 코멘트 입력 모달 */}
                {showCommentBox && selection && (
                  <div
                    style={{
                      position: 'fixed',
                      left: 0,
                      top: 0,
                      width: '100vw',
                      height: '100vh',
                      background: 'rgba(0,0,0,0.25)',
                      zIndex: 1000,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}
                  >
                    <div
                      style={{
                        background: '#fff',
                        border: '1.5px solid #bfc8e6',
                        borderRadius: 10,
                        boxShadow: '0 4px 24px rgba(0,0,0,0.13)',
                        padding: '28px 22px 18px 22px',
                        minWidth: 320,
                        maxWidth: 420,
                        width: '90vw',
                        position: 'relative',
                      }}
                    >
                      <div style={{ fontWeight: 600, fontSize: '1.13em', marginBottom: 10, color: '#2d5be3' }}>코멘트 입력</div>
                      <div style={{ fontSize: '1em', color: '#333', marginBottom: 10, background: '#f6f8fc', borderRadius: 4, padding: '7px 10px' }}>
                        "{selection.text}"
                      </div>
                      <textarea
                        style={{ width: '100%', minHeight: 60, fontSize: '1.07em', borderRadius: 6, border: '1.5px solid #bfc8e6', padding: 8, marginBottom: 12, resize: 'vertical' }}
                        placeholder="코멘트 내용을 입력하세요"
                        value={commentInput}
                        onChange={e => setCommentInput(e.target.value)}
                        autoFocus
                      />
                      <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
                        <Button size="sm" onClick={() => {
                          if (!commentInput.trim()) return;
                          console.log('[코멘트 저장]', { ...selection, comment: commentInput });
                          setCommentRanges(ranges => [...ranges, { ...selection, comment: commentInput }]);
                          setShowCommentBox(false);
                          setSelection(null);
                          setCommentInput('');
                        }}>저장</Button>
                        <Button size="sm" variant="outline" onClick={() => {
                          setShowCommentBox(false);
                          setSelection(null);
                          setCommentInput('');
                        }}>취소</Button>
                      </div>
                      <button
                        onClick={() => {
                          setShowCommentBox(false);
                          setSelection(null);
                          setCommentInput('');
                        }}
                        style={{
                          position: 'absolute',
                          top: 10,
                          right: 14,
                          background: 'none',
                          border: 'none',
                          fontSize: 22,
                          color: '#bfc8e6',
                          cursor: 'pointer',
                        }}
                        aria-label="닫기"
                      >×</button>
                    </div>
                  </div>
                )}
              </>
            ) : (
              <span style={{ color: '#aaa' }}>아직 제출된 글이 없습니다.</span>
            )}
 
          </div>
          {/* 3. 피드백 */}
          <div style={{ flex: '1 1 0', minWidth: 0, background: '#eaf0fb', borderRadius: 10, padding: '1.2em 1em', fontSize: '1.07em', boxSizing: 'border-box', wordBreak: 'break-all' }}>
            <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 8 }}>피드백</div>
        
            <textarea
              style={{ width: '100%', minHeight: 120, fontSize: '1.05em', borderRadius: 6, border: '1.5px solid #bfc8e6', padding: 8, marginTop: 4, resize: 'vertical' }}
              placeholder="피드백 입력..."
              value={feedbackValue}
              onChange={e => setFeedbackValue(e.target.value)}
              disabled={!student.submitted || saving}
            />
            <div style={{ display: 'flex', gap: 10, marginTop: 8 }}>
              <Button
                size="sm"
                style={{ flex: 1, fontWeight: allowRewrite ? 700 : 500, background: allowRewrite ? '#2d5be3' : undefined, color: allowRewrite ? '#fff' : undefined }}
                disabled={!student.submitted || saving || !feedbackValue.trim()}
                onClick={() => { setAllowRewrite(true); handleSaveFeedback(); }}
              >
                피드백 후 재작성 허용
              </Button>
              <Button
                size="sm"
                style={{ flex: 1, fontWeight: !allowRewrite ? 700 : 500, background: !allowRewrite ? '#e33d2d' : undefined, color: !allowRewrite ? '#fff' : undefined }}
                disabled={!student.submitted || saving || !feedbackValue.trim()}
                onClick={() => { setAllowRewrite(false); handleSaveFeedback(); }}
              >
                글쓰기 종료
              </Button>
            </div>
            {/* 피드백 이력(버전) */}
            <div style={{ marginTop: 18 }}>
              <b>피드백 이력</b>
              <div style={{ fontSize: '0.97em', color: '#234', marginTop: 4, maxHeight: 120, overflowY: 'auto', background: '#f6f8fc', borderRadius: 6, padding: '6px 8px' }}>
                {feedbackHistory.length === 0 ? (
                  <span style={{ color: '#aaa' }}>이력이 없습니다.</span>
                ) : (
                  feedbackHistory.map((h, idx) => (
                    <div key={idx} style={{ marginBottom: 6 }}>
                      <span style={{ color: '#2d5be3', fontWeight: 500 }}>{h.created_at?.slice(0,16).replace('T',' ') || '-'}</span><br/>
                      <span>{h.feedback}</span>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </Wrapper>
  );
}
 // 글에 코멘트 하이라이트 렌더링
  function renderWritingWithComments(text, ranges) {
    if (!ranges || ranges.length === 0) return text;
    // ranges를 start 기준 정렬, 겹치는 구간은 무시(혹은 병합)
    const sorted = [...ranges].sort((a, b) => a.start - b.start);
    const result = [];
    let last = 0;
    sorted.forEach((r, i) => {
      // 방어: 범위가 잘못된 경우 skip
      if (r.start < last || r.start >= r.end || r.end > text.length) return;
      if (last < r.start) result.push(text.slice(last, r.start));
      result.push(
        <span
          key={i}
          style={{ background: '#ffeeba', borderRadius: 3, cursor: 'pointer', border: '1px solid #ffe199', padding: '0 2px' }}
          title={r.comment}
          onClick={() => window.alert(r.comment)}
        >
          {text.slice(r.start, r.end)}
        </span>
      );
      last = r.end;
    });
    if (last < text.length) result.push(text.slice(last));
    return result;
  }
export default TeacherStudentDetail;
