import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';
import Modal from '../components/Modal';
import Input from '../components/Input';

const Wrapper = styled.div`
  max-width: 480px;
  margin: 3em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;

const Label = styled.label`
  display: block;
  margin-bottom: 0.5em;
  font-weight: 600;
`;

function randomCode() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

function TeacherSessionCreate({ user, onCreated }) {
  const navigate = useNavigate();
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [criteria, setCriteria] = useState('');
  const [date, setDate] = useState('');
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState('');

  const handleCreate = async () => {
    if (!title.trim()) {
      setError('세션명을 입력하세요.');
      return;
    }
    setCreating(true);
    setError('');
    try {
      const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(user?.access_token ? { 'Authorization': `Bearer ${user.access_token}` } : {})
        },
        body: JSON.stringify({
          title,
          desc,
          criteria,
          date,
          code: randomCode(),
          teacherId: user.id,
        })
      });
      if (!res.ok) throw new Error('세션 생성 실패');
      const data = await res.json();
      if (onCreated) onCreated(data.session);
      // 세션 생성 성공 시 상세페이지로 이동
      if (data.session && data.session.id) {
        navigate(`/teacher/sessions/${data.session.id}`);
      }
    } catch (e) {
      setError(e.message || '세션 생성 중 오류');
    } finally {
      setCreating(false);
    }
  };

  return (
    <Wrapper>
      <Title>새 세션 만들기</Title>
      <div style={{ marginBottom: 18 }}>
        <Label>세션명 *</Label>
        <Input value={title} onChange={e => setTitle(e.target.value)} maxLength={30} placeholder="예: 환경 글쓰기" disabled={creating} />
      </div>
      <div style={{ marginBottom: 18 }}>
        <Label>설명</Label>
        <Input value={desc} onChange={e => setDesc(e.target.value)} maxLength={100} placeholder="세션 설명 (선택)" disabled={creating} />
      </div>
      <div style={{ marginBottom: 18 }}>
        <Label>평가 기준</Label>
        <Input value={criteria} onChange={e => setCriteria(e.target.value)} maxLength={100} placeholder="예: 논리성, 창의성 등" disabled={creating} />
      </div>
      <div style={{ marginBottom: 18 }}>
        <Label>마감일</Label>
        <Input type="date" value={date} onChange={e => setDate(e.target.value)} disabled={creating} />
      </div>
      {error && <div style={{ color: 'red', marginBottom: 12 }}>{error}</div>}
      <Button onClick={handleCreate} disabled={creating || !title.trim()} style={{ width: '100%' }}>
        {creating ? '생성 중...' : '세션 생성'}
      </Button>
    </Wrapper>
  );
}

export default TeacherSessionCreate;
