import React from 'react';

function SubmitNotice({ submittedAt }) {
  return (
    <div
      style={{
        background: '#eaf0fb',
        color: '#2d5be3',
        borderRadius: 10,
        padding: '1em',
        marginBottom: 18,
        textAlign: 'center',
        fontWeight: 600,
        fontSize: '1.08em',
      }}
    >
      제출이 완료되었습니다. 더 이상 수정할 수 없습니다.<br />
      {submittedAt && (
        <span style={{ color: '#555', fontWeight: 400, fontSize: '0.98em' }}>
          제출 시각: {submittedAt.getFullYear()}-{(submittedAt.getMonth() + 1).toString().padStart(2, '0')}-{submittedAt.getDate().toString().padStart(2, '0')} {submittedAt.getHours().toString().padStart(2, '0')}:{submittedAt.getMinutes().toString().padStart(2, '0')}
        </span>
      )}
    </div>
  );
}

export default SubmitNotice;
