
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';
import Input from '../components/Input';
import { createClient } from '@supabase/supabase-js';

// Supabase 클라이언트 초기화 (환경변수 또는 직접 입력)
const supabaseUrl = process.env.REACT_APP_SUPABASE_URL || 'https://mrhjgypabwcewssprebi.supabase.co';
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1yaGpneXBhYndjZXdzc3ByZWJpIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NDkzNTEwNjUsImV4cCI6MjA2NDkyNzA2NX0.LH8y4qbi26ciATKtCOH7RFVj5-cuVQpmwVVoz8ULhxY';
const supabase = createClient(supabaseUrl, supabaseAnonKey);

const Wrapper = styled.div`
  max-width: 400px;
  margin: 6em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;


function TeacherLogin({ onLogin, loading }) {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(null);
  const [mode, setMode] = useState('login'); // 'login' | 'signup'
  const [pending, setPending] = useState(false);

  // Supabase 로그인
  const handleLogin = async (e) => {
    e.preventDefault();
    setError(null);
    if (!email.trim() || !password.trim()) {
      setError('이메일과 비밀번호를 입력하세요.');
      return;
    }
    setPending(true);
    const { error: loginError, data, user } = await supabase.auth.signInWithPassword({ email, password });
    setPending(false);
    if (loginError) {
      setError('로그인에 실패했습니다. ' + loginError.message);
      return;
    }
    // 상위로 유저 정보 전달
    if (onLogin) onLogin(email, password, data?.user || user);
    // 로그인 성공 시 세션 목록으로 이동
    navigate('/teacher/sessions');
  };

  // Supabase 회원가입
  const handleSignup = async (e) => {
    e.preventDefault();
    setError(null);
    if (!email.trim() || !password.trim()) {
      setError('이메일과 비밀번호를 입력하세요.');
      return;
    }
    setPending(true);
    const { error: signupError } = await supabase.auth.signUp({ email, password });
    setPending(false);
    if (signupError) {
      setError('회원가입에 실패했습니다. ' + signupError.message);
      return;
    }
    setMode('login');
    setError('회원가입이 완료되었습니다. 이메일 인증 후 로그인하세요.');
  };

  return (
    <Wrapper>
      <Title>교사 {mode === 'login' ? '로그인' : '회원가입'}</Title>
      <form onSubmit={mode === 'login' ? handleLogin : handleSignup}>
        <Input
          type="email"
          placeholder="이메일"
          value={email}
          onChange={e => setEmail(e.target.value)}
          autoFocus
          style={{ marginBottom: 16 }}
          disabled={loading || pending}
        />
        <Input
          type="password"
          placeholder="비밀번호"
          value={password}
          onChange={e => setPassword(e.target.value)}
          style={{ marginBottom: 16 }}
          disabled={loading || pending}
        />
        {error && <div style={{ color: '#e33d2d', marginBottom: 12 }}>{error}</div>}
        <Button type="submit" style={{ width: '100%' }} disabled={loading || pending}>
          {pending ? (mode === 'login' ? '로그인 중...' : '회원가입 중...') : (mode === 'login' ? '로그인' : '회원가입')}
        </Button>
      </form>
      <div style={{ marginTop: 18, textAlign: 'center' }}>
        {mode === 'login' ? (
          <>
            <span>계정이 없으신가요? </span>
            <Button variant="text" size="sm" onClick={() => { setMode('signup'); setError(null); }} style={{ padding: 0, minWidth: 0 }}>회원가입</Button>
          </>
        ) : (
          <>
            <span>이미 계정이 있으신가요? </span>
            <Button variant="text" size="sm" onClick={() => { setMode('login'); setError(null); }} style={{ padding: 0, minWidth: 0 }}>로그인</Button>
          </>
        )}
      </div>
      <Button
        variant="outline"
        style={{ width: '100%', marginTop: 18, fontSize: '1.07em' }}
        onClick={() => navigate('/')}
      >
        처음화면으로 돌아가기
      </Button>
    </Wrapper>
  );
}

export default TeacherLogin;
