import React, { useState } from 'react';
import styled from 'styled-components';
import Button from '../components/Button';
import CriteriaBox from '../components/CriteriaBox';

const Wrapper = styled.div`
  max-width: 700px;
  margin: 3em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
  min-height: 60vh;
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;

const FeedbackBox = styled.div`
  background: #eaf0fb;
  border-radius: 0.7em;
  padding: 1em 1em 0.7em 1em;
  margin-bottom: 1.2em;
  color: #234;
  font-size: 1.08em;
`;




function FeedbackView() {
  const [showCriteria, setShowCriteria] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [content, setContent] = useState('');
  const [comments, setComments] = useState([]); // [{start, end, text, color}]
  const [overall, setOverall] = useState('');
  const [allowRewrite, setAllowRewrite] = useState(false);
  const [rewriteSubmitted, setRewriteSubmitted] = useState(false);
  const [rewriteSubmittedAt, setRewriteSubmittedAt] = useState(null);
  const [rewriteValue, setRewriteValue] = useState('');

  // sessionCode, studentName은 localStorage 등에서 불러옴 (실서비스에서는 상태/props 등에서 받아야 함)
  const sessionCode = localStorage.getItem('session_code') || 'ABC123';
  const studentName = localStorage.getItem('student_name') || '홍길동';

  // 최초 데이터 fetch (피드백/코멘트/재작성 허용)
  React.useEffect(() => {
    let ignore = false;
    async function fetchFeedback() {
      setLoading(true);
      setError(null);
      try {
        const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/student-detail', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessionId: sessionCode, studentName })
        });
        if (!res.ok) throw new Error('피드백 조회 실패');
        const data = await res.json();
        if (ignore) return;
        setContent(data.student?.writing || '');
        // commentRanges: [{start, end, comment}]
        setComments((data.comments || []).map(c => ({
          start: c.start,
          end: c.end,
          text: c.comment,
          color: '#2d5be3', // 기본 색상, 필요시 개선
        })));
        setOverall(data.student?.feedback || '');
        setAllowRewrite(typeof data.allowRewrite === 'boolean' ? data.allowRewrite : !!data.student?.allowRewrite);
        // 재작성 제출 여부/시각 (백엔드에서 최신 글 version/is_latest로 판별)
        setRewriteSubmitted(!!data.student?.rewrite_submitted);
        setRewriteSubmittedAt(data.student?.rewrite_submitted_at ? new Date(data.student.rewrite_submitted_at) : null);
        setRewriteValue(data.student?.rewrite_content || data.student?.writing || '');
      } catch (e) {
        setError(e.message);
      } finally {
        setLoading(false);
      }
    }
    fetchFeedback();
    return () => { ignore = true; };
  }, [sessionCode, studentName]);


  // 글 제출/재작성 API 연동 함수 (버전 자동 관리)
  async function submitRewrite({ sessionCode, studentName, content }) {
    const API_URL = 'https://mrhjgypabwcewssprebi.supabase.co/functions/v1/writings-rewrite';
    const res = await fetch(API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_code: sessionCode,
        student_name: studentName,
        content,
        // version은 백엔드에서 자동 증가
      }),
    });
    return await res.json();
  }


  // 재작성 제출 핸들러
  const handleRewriteSubmit = async () => {
    if (!rewriteValue.trim()) {
      alert('수정/재작성 내용을 입력하세요.');
      return;
    }
    if (!window.confirm('재작성 글을 제출하시겠습니까? 제출 후에는 수정할 수 없습니다.')) return;
    try {
      const result = await submitRewrite({ sessionCode, studentName, content: rewriteValue });
      if (!result.ok) throw new Error(result.error || '제출 실패');
      setRewriteSubmitted(true);
      setRewriteSubmittedAt(new Date(result.submitted_at || Date.now()));
    } catch (err) {
      alert('제출에 실패했습니다: ' + err.message);
    }
  };

  // 본문에 말풍선 코멘트 표시 (마우스오버/터치 시만 피드백 노출)
  const renderContentWithComments = () => {
    if (!content) return null;
    let result = [];
    let lastIdx = 0;
    comments.forEach((c, i) => {
      if (c.start > lastIdx) {
        result.push(<span key={lastIdx}>{content.slice(lastIdx, c.start)}</span>);
      }
      result.push(
        <FeedbackComment
          key={c.start}
          text={content.slice(c.start, c.end)}
          comment={c.text}
          color={c.color}
        />
      );
      lastIdx = c.end;
    });
    if (lastIdx < content.length) {
      result.push(<span key={lastIdx}>{content.slice(lastIdx)}</span>);
    }
    return result;
  };

  // 말풍선 코멘트 컴포넌트 (hover/touch 시만 피드백 노출)
  function FeedbackComment({ text, comment, color }) {
    const [show, setShow] = useState(false);
    return (
      <span
        style={{
          background: 'linear-gradient(90deg, #ffe9b3 60%, #ffe3a1 100%)',
          borderRadius: 5,
          position: 'relative',
          padding: '0 2px',
          cursor: 'pointer',
          transition: 'background 0.2s',
          boxShadow: '0 0 0 2px #ffe3a1',
        }}
        onMouseEnter={() => setShow(true)}
        onMouseLeave={() => setShow(false)}
        onTouchStart={e => { e.stopPropagation(); setShow(s => !s); }}
        tabIndex={0}
        aria-label={comment}
      >
        {text}
        {show && (
          <span
            style={{
              position: 'absolute',
              left: 0,
              top: '100%',
              background: color,
              color: '#fff',
              borderRadius: 6,
              fontSize: '0.97em',
              padding: '0.2em 0.7em',
              marginTop: 2,
              whiteSpace: 'nowrap',
              zIndex: 10,
              boxShadow: '0 2px 8px rgba(0,0,0,0.13)',
              minWidth: 80,
              maxWidth: 220,
            }}
          >
            {comment}
          </span>
        )}
      </span>
    );
  }

  if (loading) {
    return <Wrapper><div style={{ textAlign: 'center', color: '#888', marginTop: 60 }}>로딩 중...</div></Wrapper>;
  }
  if (error) {
    return <Wrapper><div style={{ textAlign: 'center', color: '#c00', marginTop: 60 }}>{error}</div></Wrapper>;
  }
  return (
    <Wrapper>
      <Title>피드백 확인</Title>
      {/* 제출 이력/버전 정보 표시 */}
      {rewriteSubmitted && (
        <div style={{
          background: '#eaf0fb',
          color: '#2d5be3',
          borderRadius: 10,
          padding: '0.7em 1em',
          marginBottom: 16,
          textAlign: 'center',
          fontWeight: 600,
          fontSize: '1.07em',
        }}>
          2번째 제출본입니다. 더 이상 수정할 수 없습니다.<br />
          {rewriteSubmittedAt && (
            <span style={{ color: '#555', fontWeight: 400, fontSize: '0.98em' }}>
              제출 시각: {rewriteSubmittedAt.getFullYear()}-{(rewriteSubmittedAt.getMonth() + 1).toString().padStart(2, '0')}-{rewriteSubmittedAt.getDate().toString().padStart(2, '0')} {rewriteSubmittedAt.getHours().toString().padStart(2, '0')}:{rewriteSubmittedAt.getMinutes().toString().padStart(2, '0')}
            </span>
          )}
        </div>
      )}
      <div style={{ marginBottom: 18, display: 'flex', gap: 12, alignItems: 'center' }}>
        <label style={{ userSelect: 'none', fontSize: '1em', color: '#234', cursor: 'pointer' }}>
          <input
            type="checkbox"
            checked={showCriteria}
            onChange={e => setShowCriteria(e.target.checked)}
            style={{ marginRight: 6, accentColor: '#2d5be3' }}
          />
          평가 기준 보기
        </label>
      </div>
      {showCriteria && (
        <CriteriaBox>
          <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 6, fontSize: '1.08em' }}>평가 기준</div>
          <b>평가 기준 예시</b><br />
          1. 주제에 맞는 글을 썼는가?<br />
          2. 문단 구성이 논리적인가?<br />
          3. 맞춤법과 띄어쓰기가 올바른가?<br />
          4. 자신의 생각이 잘 드러나는가?<br />
          <span style={{ color: '#888', fontSize: '0.97em' }}>(실제 기준은 세션별로 다를 수 있습니다)</span>
        </CriteriaBox>
      )}
      <FeedbackBox>
        <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 6, fontSize: '1.08em' }}>전체 피드백</div>
        {overall || <span style={{ color: '#aaa' }}>피드백이 없습니다.</span>}
      </FeedbackBox>
      <div style={{ background: '#f9f9f9', borderRadius: 8, padding: '1.2em 1em', minHeight: 120, fontSize: '1.13em', marginBottom: 18, position: 'relative' }}>
        <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 6, fontSize: '1.08em' }}>내가 제출한 글</div>
        {renderContentWithComments()}
      </div>
      {allowRewrite ? (
        !rewriteSubmitted ? (
          <div style={{ marginTop: 24 }}>
            <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 6, fontSize: '1.08em' }}>수정하기</div>
            <textarea
              style={{ width: '100%', minHeight: 120, fontSize: '1.1em', borderRadius: 8, border: '1.5px solid #bfc8e6', padding: 12, marginBottom: 12 }}
              placeholder="수정/재작성 내용을 입력하세요..."
              value={rewriteValue}
              onChange={e => setRewriteValue(e.target.value)}
              disabled={rewriteSubmitted}
            />
            <Button style={{ width: '100%' }} onClick={handleRewriteSubmit} disabled={rewriteSubmitted}>
              재작성 제출
            </Button>
          </div>
        ) : null
      ) : (
        <div style={{ marginTop: 24, color: '#888', textAlign: 'center', fontSize: '1.08em' }}>
          재작성은 허용되지 않습니다. 글쓰기가 완료되었습니다.
        </div>
      )}
    </Wrapper>
  );
}

export default FeedbackView;
