import React from 'react';
import styled from 'styled-components';

const HeaderWrap = styled.header`
  width: 100%;
  background: #2d5be3;
  color: #fff;
  padding: 1.2rem 0;
  text-align: center;
  font-size: 1.5rem;
  font-weight: bold;
  letter-spacing: 0.05em;
`;

function Header() {
  return <HeaderWrap>학교 글쓰기 플랫폼</HeaderWrap>;
}

export default Header;
