import React, { useState, useRef, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

import styled from 'styled-components';
import Button from '../components/Button';
import CriteriaBox from '../components/CriteriaBox';
import SubmitNotice from '../components/SubmitNotice';

const Wrapper = styled.div`
  max-width: ${({ $fullscreen }) => ($fullscreen ? '100vw' : '700px')};
  width: 100%;
  margin: ${({ $fullscreen }) => ($fullscreen ? '0' : '3em auto 0 auto')};
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: ${({ $fullscreen }) => ($fullscreen ? '2vw 2vw 40px 2vw' : '2.5em 2em 2em 2em')};
  min-height: ${({ $fullscreen }) => ($fullscreen ? '100vh' : '60vh')};
  position: ${({ $fullscreen }) => ($fullscreen ? 'fixed' : 'static')};
  top: 0; left: 0; right: 0; bottom: 0;
  z-index: ${({ $fullscreen }) => ($fullscreen ? 3000 : 'auto')};
  transition: all 0.2s;
  overflow-y: auto;
  @media (max-width: 900px) {
    max-width: 100vw;
    padding: ${({ $fullscreen }) => ($fullscreen ? '2vw 2vw 40px 2vw' : '1em')};
  }
`;

const Title = styled.h2`
  margin-bottom: 1.5em;
  font-size: 1.5em;
  color: ${({ theme }) => theme.primary};
`;

const Editor = styled.textarea`
  width: 100%;
  min-height: 250px;
  font-size: 1.2em;
  padding: 1em;
  border-radius: 0.7em;
  border: 1.5px solid #bfc8e6;
  resize: vertical;
  margin-bottom: 1em;
  background: ${({ theme }) => theme.background};
  color: ${({ theme }) => theme.text};
`;


function WritingEditor() {
  // 쿼리스트링에서 code, name 추출
  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const sessionCode = params.get('code') || '';
  const studentName = params.get('name') || '';
  const [content, setContent] = useState('');
  const [fullscreen, setFullscreen] = useState(false);
  const [showCriteria, setShowCriteria] = useState(false);
  const [criteria, setCriteria] = useState('');
  const [saveStatus, setSaveStatus] = useState('idle'); // idle | saving | saved | error
  const [lastSaved, setLastSaved] = useState(null);
  const [submitted, setSubmitted] = useState(() => {
    // 새로고침 시에도 제출 상태 유지 (mock)
    return !!localStorage.getItem('writing_submitted');
  });
  const [submittedAt, setSubmittedAt] = useState(() => {
    const t = localStorage.getItem('writing_submitted_at');
    return t ? new Date(Number(t)) : null;
  });
  const saveTimeout = useRef(null);
  const autoSaveInterval = useRef(null);

  // 세션 criteria 불러오기
  useEffect(() => {
    async function fetchCriteria() {
      if (!sessionCode) return;
      try {
        const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-detail', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: sessionCode })
        });
        if (!res.ok) throw new Error('세션 정보 조회 실패');
        const data = await res.json();
        let session = data.session || data;
        setCriteria(session.criteria || '');
      } catch {
        setCriteria('');
      }
    }
    fetchCriteria();
  }, [sessionCode]);

  // 임시 저장 함수 (DB 연동)
  const saveContent = async (manual = false) => {
    setSaveStatus('saving');
    try {
      // DB에 임시저장 (student_entries.draft_content)
      await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/save-draft', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_code: sessionCode, student_name: studentName, draft_content: content })
      });
      setSaveStatus('saved');
      setLastSaved(new Date());
      if (manual) {
        clearTimeout(saveTimeout.current);
        saveTimeout.current = setTimeout(() => setSaveStatus('idle'), 1500);
      }
    } catch (e) {
      setSaveStatus('error');
    }
  };

  // 30초마다 자동 저장
  useEffect(() => {
    autoSaveInterval.current = setInterval(() => {
      saveContent();
      setLastSaved(new Date()); // 저장 시각을 항상 갱신
    }, 30000);
    return () => {
      clearInterval(autoSaveInterval.current);
      clearTimeout(saveTimeout.current);
    };
    // eslint-disable-next-line
  }, [content]);

  // 최초 진입 시 draft 불러오기 (DB에서)
  useEffect(() => {
    async function fetchDraft() {
      if (!sessionCode || !studentName) return;
      try {
        const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/get-draft', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ session_code: sessionCode, student_name: studentName })
        });
        if (!res.ok) return;
        const data = await res.json();
        if (data && typeof data.draft_content === 'string') setContent(data.draft_content);
      } catch {}
    }
    fetchDraft();
  }, [sessionCode, studentName]);

  // 저장 상태 텍스트
  const getSaveStatusText = () => {
    if (saveStatus === 'saving') return '저장 중...';
    if (saveStatus === 'saved') return '저장됨';
    if (saveStatus === 'error') return '저장 실패';
    return '';
  };

  // 마지막 저장 시각 텍스트
  const getLastSavedText = () => {
    if (lastSaved) {
      const t = lastSaved;
      return `마지막 저장: ${t.getHours().toString().padStart(2, '0')}:${t.getMinutes().toString().padStart(2, '0')}:${t.getSeconds().toString().padStart(2, '0')}`;
    }
    return '';
  };

  // 실제 API 연동 함수 (최초 제출)
  async function submitWriting({ sessionCode, studentName, content }) {
    // Supabase Edge Function 연동
    const API_URL = 'https://mrhjgypabwcewssprebi.supabase.co/functions/v1/writings-submit';
    try {
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          session_code: sessionCode,
          student_name: studentName,
          content,
        }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.error || '서버 오류');
      }
      return await res.json();
    } catch (e) {
      throw new Error(e.message || '서버 오류');
    }
  }


  return (
    <Wrapper $fullscreen={fullscreen}>
      {submitted && <SubmitNotice submittedAt={submittedAt} />}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24, gap: 12 }}>
        <Title style={{ marginBottom: 0 }}>글쓰기</Title>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <label style={{ userSelect: 'none', fontSize: '1em', color: '#234', cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={showCriteria}
              onChange={e => setShowCriteria(e.target.checked)}
              style={{ marginRight: 6, accentColor: '#2d5be3' }}
            />
            평가 기준 보기
          </label>
          <Button
            variant="outline"
            style={{ minWidth: 90, fontSize: '1em', padding: '0.5em 1em', marginLeft: 8 }}
            onClick={() => setFullscreen(f => !f)}
          >
            {fullscreen ? '전체화면 해제' : '전체화면'}
          </Button>
        </div>
      </div>
      {showCriteria && (
        <CriteriaBox>
          <b>평가 기준</b><br />
          {criteria
            ? criteria.split('\n').map((line, idx) => <span key={idx}>{line}<br /></span>)
            : <span style={{ color: '#aaa' }}>평가 기준이 없습니다.</span>}
        </CriteriaBox>
      )}
      <Editor
        placeholder="여기에 글을 작성하세요..."
        value={content}
        onChange={e => setContent(e.target.value)}
        style={fullscreen ? { minHeight: '60vh', fontSize: '1.3em' } : {}}
        disabled={submitted}
      />
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <span style={{ color: '#888' }}>글자수: {content.length}자</span>
        <span style={{ color: saveStatus === 'error' ? '#e33' : '#888', fontSize: '0.98em' }}>{getSaveStatusText()}</span>
      </div>
      <div style={{ textAlign: 'right', color: '#888', fontSize: '0.97em', marginBottom: 8 }}>
        {getLastSavedText()}
      </div>
      <div style={{ display: 'flex', gap: 12, marginTop: 24, marginBottom: fullscreen ? 24 : 8, justifyContent: 'center' }}>
        <Button 
          style={{ 
            flex: 1, 
            maxWidth: 180, 
            borderRadius: 8, 
            fontSize: fullscreen ? '1.15em' : undefined, 
            marginBottom: fullscreen ? 16 : 0 
          }} 
          onClick={() => saveContent(true)} 
          disabled={saveStatus === 'saving' || submitted}
        >
          {saveStatus === 'saving' ? '저장 중...' : '임시 저장'}
        </Button>
        <Button
          style={{ flex: 1, maxWidth: 180, background: '#2db37c', border: 'none', borderRadius: 8, fontSize: fullscreen ? '1.15em' : undefined, marginBottom: fullscreen ? 16 : 0 }}
          onClick={async () => {
            if (!content.trim()) {
              alert('글을 입력하세요.');
              return;
            }
            if (window.confirm('글을 제출하시겠습니까? 제출 후에는 수정할 수 없습니다.')) {
              try {
                const result = await submitWriting({ sessionCode, studentName, content });
                if (!result.ok) throw new Error('제출 실패');
                setSubmitted(true);
                setSubmittedAt(new Date(result.submitted_at || Date.now()));
                // localStorage.setItem('writing_submitted', content); // 실제 저장은 백엔드에서 관리
                // localStorage.setItem('writing_submitted_at', (result.submitted_at || Date.now()).toString());
              } catch (err) {
                alert('제출에 실패했습니다: ' + err.message);
              }
            }
          }}
          disabled={submitted}
        >
          {submitted ? '제출 완료' : '제출하기'}
        </Button>
      </div>
    </Wrapper>
  );
}

export default WritingEditor;
