import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import styled from 'styled-components';
import Button from '../components/Button';

const Wrapper = styled.div`
  max-width: 1500px;
  margin: 3em auto 0 auto;
  background: ${({ theme }) => theme.card};
  border-radius: 1.2em;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 2.5em 2em 2em 2em;
  min-height: 60vh;
`;

const TwoCol = styled.div`
  display: flex;
  gap: 32px;
  min-height: 500px;
`;
const LeftCol = styled.div`
  flex: 0 0 340px;
  background: #f5f8ff;
  border-radius: 10px;
  padding: 1.2em 1em;
  display: flex;
  flex-direction: column;
  height: 100%;
`;
const RightCol = styled.div`
  flex: 1 1 0;
  background: #fff;
  border-radius: 10px;
  padding: 1.2em 1.5em;
  min-height: 420px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.04);
  display: flex;
  flex-direction: column;
`;
const ChatBox = styled.div`
  flex: 1 1 0;
  min-height: 260px;
  overflow-y: auto;
  margin-bottom: 1em;
  background: #fafdff;
  border-radius: 8px;
  padding: 1em;
  border: 1px solid #e3eaf7;
`;
const ChatInputRow = styled.div`
  display: flex;
  gap: 8px;
`;

function TeacherSessionAllWritings() {
  const { id } = useParams(); // 세션 id
  const [writings, setWritings] = useState([]); // [{student_name, content, ...}]
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [chat, setChat] = useState([]); // [{role: 'user'|'ai', text}]
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(true);

  // 세션 내 모든 글 fetch
  useEffect(() => {
    let ignore = false;
    async function fetchAllWritings() {
      setLoading(true);
      try {
        const res = await fetch('https://mrhjgypabwcewssprebi.supabase.co/functions/v1/session-all-writings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessionId: id })
        });
        const data = await res.json();
        if (!ignore) setWritings(data.writings || []);
      } catch (e) {
        if (!ignore) setWritings([]);
      } finally {
        setLoading(false);
      }
    }
    fetchAllWritings();
    return () => { ignore = true; };
  }, [id]);

  // 채팅 전송 핸들러 (AI 연동은 실제 API 필요, 여기선 더미)
  const handleSend = async () => {
    if (!input.trim()) return;
    setChat(chat => [...chat, { role: 'user', text: input }]);
    setInput('');
    // 실제 AI 연동 시 아래 fetch 등으로 대체
    setTimeout(() => {
      setChat(chat => [...chat, { role: 'ai', text: 'AI 답변 예시: ' + input }]);
    }, 800);
  };

  const selectedWriting = writings[selectedIdx] || {};

  return (
    <Wrapper>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: '1.5em', gap: 12 }}>
        <h2 style={{ color: '#2d5be3', margin: 0, flex: 1 }}>세션 전체 글 열람</h2>
        <Button variant="outline" size="sm" onClick={() => window.history.length > 1 ? window.history.back() : window.location.assign('/feed_writer/')}>뒤로가기</Button>
        <Button variant="outline" size="sm" onClick={() => window.location.assign('/feed_writer/')}>처음화면</Button>
      </div>
      {loading ? (
        <div style={{ textAlign: 'center', color: '#888', marginTop: 60 }}>로딩 중...</div>
      ) : writings.length === 0 ? (
        <div style={{ textAlign: 'center', color: '#c00', marginTop: 60 }}>글 데이터가 없습니다.</div>
      ) : (
        <TwoCol>
          {/* 왼쪽: 채팅창 */}
          <LeftCol>
            <div style={{ fontWeight: 700, color: '#2d5be3', marginBottom: 10, fontSize: '1.13em' }}>AI 챗봇</div>
            <ChatBox>
              {chat.length === 0 ? (
                <div style={{ color: '#aaa', textAlign: 'center', marginTop: 30 }}>AI와의 대화가 없습니다.</div>
              ) : (
                chat.map((msg, idx) => (
                  <div key={idx} style={{
                    marginBottom: 10,
                    textAlign: msg.role === 'user' ? 'right' : 'left',
                  }}>
                    <span style={{
                      display: 'inline-block',
                      background: msg.role === 'user' ? '#e3eaf7' : '#2d5be3',
                      color: msg.role === 'user' ? '#234' : '#fff',
                      borderRadius: 8,
                      padding: '7px 13px',
                      maxWidth: 220,
                      fontSize: '1.05em',
                    }}>{msg.text}</span>
                  </div>
                ))
              )}
            </ChatBox>
            <ChatInputRow>
              <input
                type="text"
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') handleSend(); }}
                placeholder="AI에게 질문..."
                style={{ flex: 1, fontSize: '1.07em', borderRadius: 6, border: '1.5px solid #bfc8e6', padding: '7px 10px' }}
              />
              <Button size="sm" onClick={handleSend} disabled={!input.trim()}>전송</Button>
            </ChatInputRow>
          </LeftCol>
          {/* 오른쪽: 글 내용 */}
          <RightCol>
            <div style={{ marginBottom: 18, display: 'flex', gap: 10, alignItems: 'center' }}>
              <span style={{ fontWeight: 700, color: '#2d5be3', fontSize: '1.13em' }}>글 목록</span>
              <select
                value={selectedIdx}
                onChange={e => setSelectedIdx(Number(e.target.value))}
                style={{ marginLeft: 10, fontSize: '1.07em', borderRadius: 6, border: '1.5px solid #bfc8e6', padding: '4px 10px' }}
              >
                {writings.map((w, idx) => (
                  <option key={w.student_name || idx} value={idx}>
                    {w.student_name || `학생${idx+1}`}
                  </option>
                ))}
              </select>
            </div>
            <div style={{ background: '#f9f9f9', borderRadius: 8, padding: '1.2em 1em', minHeight: 220, fontSize: '1.13em', whiteSpace: 'pre-wrap', color: '#222', boxShadow: '0 1px 4px rgba(0,0,0,0.03)' }}>
              {selectedWriting.content || <span style={{ color: '#aaa' }}>글 내용이 없습니다.</span>}
            </div>
          </RightCol>
        </TwoCol>
      )}
    </Wrapper>
  );
}

export default TeacherSessionAllWritings;
